const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const confidenceText=c=>typeof c==='object'?({low:'Низкая',medium:'Средняя',high:'Высокая'}[c.level]??c.level):`${c}%`;
export function pipelinePanel(plan,data){
  const w=plan.recommended,labels=Object.fromEntries(data.factors.map(f=>[f.id,f.name]));
  const status={insufficient:'Недостаточно данных',review:'Требует проверки',acceptable:'Покрытие полное'};
  return `<section class="panel pipeline-summary"><div class="panel-heading"><h2>${plan.outcome==='insufficient'?'Оснований для выбора недостаточно':plan.improvement?'Предпочтительное окно':'Перенос не улучшает оценку'}</h2><span class="subtle-tag">PIPELINE V2</span></div><p>Уверенность: <strong>${esc(confidenceText(w.confidence))}</strong>. Механизмы сравниваются отдельно, без суммарного балла.</p><div class="table-scroll"><table><thead><tr><th>Механизм</th><th><button class="text-button" data-window="A">Окно A</button><small>${esc(new Date(plan.original.start).toISOString())}</small></th><th><button class="text-button" data-window="B" ${plan.alternative?'':'disabled'}>Окно B</button><small>${plan.alternative?esc(new Date(plan.alternative.start).toISOString()):'Нет альтернативы'}</small></th></tr></thead><tbody>${data.factors.map(f=>`<tr><td>${esc(f.name)}</td>${[plan.original,plan.alternative].map(window=>{const v=window?.factors[f.id];return `<td>${v?`${esc(status[v.status])}<small>Покрытие ${(v.coverage*100).toFixed(1)}% · ${v.value===null?'Оценка неизвестна':`${v.value.toPrecision(4)} ${esc(v.unit)}`}</small>`:'—'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><details open><summary>Причины и ограничения</summary><ul>${w.confidence.reasons.map(r=>`<li>${esc(r.detail)}</li>`).join('')}</ul></details><details><summary>Правила · ${esc(plan.rules.version)}</summary><pre>${esc(JSON.stringify(plan.rules,null,2))}</pre></details><p>${plan.cutoff?`Replay: публикации до ${esc(plan.cutoff)}. Источники без времени выпуска исключены.`:'Наблюдения не продлеваются на будущие окна как прогноз.'}</p></section>`;
}
export function pipelineSources(plan,data){return `<section class="panel pipeline-summary"><div class="panel-heading"><h2>Источники и происхождение</h2><button class="button outline" data-action="refresh">Обновить</button></div><div class="table-scroll"><table><thead><tr><th>Источник / версия</th><th>Последняя загрузка</th><th>Состояние / ограничения</th><th>Включён</th></tr></thead><tbody>${plan.sources.map(s=>`<tr><td><a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.name)}</a><small>${esc(s.version)}</small></td><td>${esc(s.lastSuccess)}<small>Публикация: ${esc(s.publishedAt)}</small></td><td>${esc(s.status)}<small>${esc(s.detail)}</small><small>В строгом replay: ${s.replayEligible?'есть датированные записи':'нет подтверждения публикации'}</small></td><td><button class="switch ${s.enabled?'on':''}" role="switch" aria-checked="${s.enabled}" data-source="${esc(s.id)}" aria-label="Источник ${esc(s.name)}"><span></span></button></td></tr>`).join('')}</tbody></table></div><h3>Покрытие рядов по всему горизонту</h3><ul>${Object.entries(data.coverage).map(([id,c])=>`<li>${esc(id)}: ${(c.fraction*100).toFixed(1)}% (${c.validSamples}/${c.expectedSamples})</li>`).join('')||'<li>Нет валидных рядов</li>'}</ul></section>`;}
export function pipelineHistory(plan,data){return `<section class="panel pipeline-summary"><h2>Исторические выпуски и независимая сверка</h2><p>В строгом replay используются только версии с подтверждённой публикацией не позже отсечения. Время скачивания и эпоха орбиты не заменяют дату выпуска.</p><p>Датированных выпусков на срезе: ${data.context.length}. Строгая воспроизводимость полного решения: ${plan.strictReproducibility?'да':'не подтверждена'}.</p>${data.context.map(r=>`<details><summary>${esc(r.sourceId)} · ${esc(r.publishedAt)}</summary><pre>${esc(typeof r.payload==='string'?r.payload:JSON.stringify(r.payload,null,2))}</pre></details>`).join('')}<p>DONKI — контекст для сверки, а не измерение потока у станции. FAR и заблаговременность требуют размеченных событий и полного архива.</p></section>`;}
